"""Absence notices to send home to parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def own_marks(
    student: Student, marks: Iterable[Mark]
) -> List[Mark]:
    found = list(marks)
    for mark in found:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id}")
    return found

def notice_text(student: Student, days: List[date]) -> str:
    """Name, count and dates of the missed days."""
    unit = "day" if len(days) == 1 else "days"
    dates = ", ".join(item.isoformat() for item in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(days)} {unit}: {dates}."

def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Note for parents listing absent days."""
    missed = days_missed(own_marks(student, marks))
    if not missed:
        raise ValueError("no absences to write about")
    return notice_text(student, missed)
